function embed(text){
  const tokens = String(text || '').toLowerCase().split(/[^a-z0-9áéíóúüñ]+/).filter(Boolean);
  const counts = {};
  for (const t of tokens) counts[t] = (counts[t] || 0) + 1;
  return counts;
}
function cosine(a,b){
  let dot=0,na=0,nb=0;
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const k of keys) {
    const va = a[k] || 0;
    const vb = b[k] || 0;
    dot += va * vb;
    na += va * va;
    nb += vb * vb;
  }
  if (!na || !nb) return 0;
  return dot / Math.sqrt(na * nb);
}
