async function httpGet(url, opts={}) {
  return await this.helpers.httpRequest({ method: 'GET', url, timeout: opts.timeout || 20000, headers: { 'User-Agent': 'n8n-catastro-bot/1.0', 'Accept': opts.accept || '*/*' } });
}
async function geocode(addr) {
  try {
    const u = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(addr)}`;
    const res = await httpGet(u, { accept: 'application/json' });
    const data = typeof res === 'string' ? JSON.parse(res) : res;
    if (Array.isArray(data) && data[0]) return { lat: +data[0].lat, lon: +data[0].lon };
  } catch (e) {}
  return null;
}
function bbox4326(lat, lon, pad=0.0006) { return `${lat-pad},${lon-pad},${lat+pad},${lon+pad}`; }
function parseTextTable(txt) {
  const lines = String(txt || '').split(/?
/);
  const out = {};
  for (const line of lines) {
    const [k,v] = line.split('	');
    if (!k) continue;
    out[k.trim()] = String(v || '').trim();
  }
  return out;
}
function toNumber(value) {
  if (value == null) return null;
  const n = Number(String(value).replace(/,/g,'.').replace(/\s+/g,''));
  return Number.isFinite(n) ? n : null;
}
function areaPerimeterXY(pts) {
  let area=0,peri=0;
  for (let i=0;i<pts.length;i++) {
    const [x1,y1]=pts[i], [x2,y2]=pts[(i+1)%pts.length];
    area += x1*y2 - x2*y1;
    peri += Math.hypot(x2-x1, y2-y1);
  }
  return { area: Math.abs(area)/2, perimeter: peri };
}
function parseGmlPositions(gml) {
  const regex=/<gml:posList[^>]*>([\s\S]*?)<\/gml:posList>/gi;
  const polys=[];
  let match;
  while((match=regex.exec(gml))){
    const nums=match[1].trim().split(/\s+/).map(Number).filter(Number.isFinite);
    if(nums.length<6) continue;
    const step = (nums.length % 3 === 0) ? 3 : 2;
    const poly=[];
    for(let i=0;i+step-1<nums.length;i+=step) poly.push([nums[i], nums[i+1]]);
    if(poly.length>=3) polys.push(poly);
  }
  return polys;
}
async function geomFromWFS(inspireId){
  const bases=['https://ovc.catastro.meh.es','http://ovc.catastro.meh.es'];
  for(const base of bases){
    const url = `${base}/INSPIRE/wfsBU.aspx?service=WFS&version=2.0.0&request=GetFeature&storedquery_id=GetBuilding&inspireId=${encodeURIComponent(inspireId)}`;
    try {
      const gml = await httpGet(url, { accept: 'application/xml,text/xml,*/*', timeout: 20000 });
      const polys = parseGmlPositions(gml);
      if (polys.length){
        let area=0,peri=0;
        for(const poly of polys){
          const geom = areaPerimeterXY(poly);
          area += geom.area;
          peri += geom.perimeter;
        }
        return { area, peri };
      }
    } catch (e) {}
  }
  return null;
}
async function getCatastro(lat, lon){
  const base='https://ovc.catastro.meh.es/cartografia/INSPIRE/spadgcwms.aspx';
  const url=`${base}?service=WMS&request=GetFeatureInfo&version=1.3.0&CRS=EPSG:4326&LAYERS=BU.Building&QUERY_LAYERS=BU.Building&WIDTH=101&HEIGHT=101&I=50&J=50&BBOX=${bbox4326(lat,lon)}&INFO_FORMAT=text/plain`;
  try {
    const txt = await httpGet(url, { accept: 'text/plain' });
    const kv = parseTextTable(txt);
    const inspireId = kv['inspireId'] || Object.values(kv).find(v => /ES\.SDGC\.BU\./.test(v)) || null;
    const dwellings = toNumber(kv['numberOfDwellings']);
    const floors = toNumber(kv['numberOfFloors']) || toNumber(kv['numberOfFloorsAboveGround']);
    let area=null, peri=null;
    if (inspireId){
      const geom = await geomFromWFS(inspireId);
      if (geom){ area = geom.area; peri = geom.peri; }
      return { inspireId, dwellings, floors, area, peri };
    }
    return { dwellings, floors, area, peri };
  } catch (e) {
    return null;
  }
}
